INSERT INTO `assignments` (`assign_id`, `class_id`, `title`, `description`, `type`, `due_date`, `max_score`, `status`, `created_at`, `updated_at`) VALUES
(1, 2, 'Grammar reflection: study goals email', 'Viet mot email ngan bang tieng Anh gioi thieu muc tieu hoc IELTS trong 8 tuan toi va nhung kho khan hien tai cua ban.', 'writing', '2026-08-15 21:00:00', 10.00, 'active', '2026-08-01 09:00:00', '2026-08-01 09:00:00'),
(2, 2, 'Connector transformation worksheet', 'Viet lai cac cau su dung although, however, therefore, in addition va because trong cac tinh huong hoc tap.', 'worksheet', '2026-08-20 21:00:00', 10.00, 'active', '2026-08-02 09:00:00', '2026-08-02 09:00:00'),
(3, 3, 'Reading scan-and-match journal', 'Ghi lai cach ban tim keyword, paraphrase va bang chung trong mot passage da hoc tren lop.', 'reflection', '2026-08-16 20:30:00', 10.00, 'active', '2026-08-03 09:00:00', '2026-08-03 09:00:00'),
(4, 4, 'Task 2 idea bank: public transport', 'Lap dan y cho de bai ve dau tu giao thong cong cong va phuong tien ca nhan, gom thesis va 2 than bai.', 'writing', '2026-08-18 21:30:00', 10.00, 'active', '2026-08-04 09:00:00', '2026-08-04 09:00:00'),
(5, 7, 'TOEIC email reply: client delay', 'Tra loi email khach hang ve viec giao hang bi tre, xac nhan thoi gian moi va de xuat cach cap nhat tiep theo.', 'writing', '2026-08-17 20:30:00', 100.00, 'active', '2026-08-05 09:00:00', '2026-08-05 09:00:00'),
(6, 8, 'Part 5 vocabulary review: HR and finance', 'Hoan thanh phieu on tap tu vung lien quan den phong nhan su, invoice, payment terms va budget approval.', 'worksheet', '2026-08-19 20:30:00', 100.00, 'active', '2026-08-06 09:00:00', '2026-08-06 09:00:00'),
(7, 11, 'Speaking log: weekend plans with a classmate', 'Tao speaking note 1 phut ve ke hoach cuoi tuan va dat it nhat 3 cau hoi follow-up.', 'speaking_note', '2026-08-21 19:30:00', 10.00, 'active', '2026-08-07 09:00:00', '2026-08-07 09:00:00'),
(8, 13, 'Business memo rewrite: scheduling update', 'Viet lai ban thong bao doi lich hop thanh mot memo ngan gon, ro doi tuong nhan va hanh dong can thuc hien.', 'writing', '2026-08-22 20:30:00', 100.00, 'active', '2026-08-08 09:00:00', '2026-08-08 09:00:00'),
(9, 15, 'Listening summary: training lecture notes', 'Nghe transcript va tong hop 5 y chinh cua bai lecture theo bullet points.', 'worksheet', '2026-08-23 20:00:00', 10.00, 'active', '2026-08-09 09:00:00', '2026-08-09 09:00:00'),
(10, 16, 'Speaking part 2 cue-card rehearsal', 'Soan note cho 1 cue card va viet 5 cum tu noi y de giu mach noi.', 'speaking_note', '2026-08-24 20:00:00', 10.00, 'active', '2026-08-10 09:00:00', '2026-08-10 09:00:00'),
(11, 1, 'Foundation exit reflection', 'Tong ket nhung thay doi ve tu vung, phat am va ky nang tu hoc sau khoa nen tang.', 'reflection', '2026-07-05 18:00:00', 10.00, 'closed', '2026-06-28 09:00:00', '2026-07-05 18:00:00'),
(12, 6, 'Starter course final vocabulary check', 'Hoan thanh bang tu vung cuoi khoa TOEIC starter theo chu de office and travel.', 'worksheet', '2026-06-25 18:00:00', 100.00, 'closed', '2026-06-18 09:00:00', '2026-06-25 18:00:00');
INSERT INTO `assignment_submissions` (`assign_submission_id`, `assign_id`, `user_id`, `content`, `answers_json`, `score`, `feedback`, `status`, `submitted_at`, `graded_at`) VALUES
(1, 1, 1, 'I want to improve reading speed, note-taking, and speaking confidence before moving to the next IELTS course. My biggest problem now is that I hesitate too long before choosing an answer in reading.', NULL, 8.50, 'Noi dung ro rang, co muc tieu hoc tap cu the. Can them 1 vi du ve cach ban se tu hoc ngoai gio.', 'graded', '2026-08-12 20:10:00', '2026-08-13 09:00:00'),
(2, 2, 1, NULL, '{\"item1\":\"although\",\"item2\":\"therefore\",\"item3\":\"because\",\"item4\":\"however\",\"item5\":\"in addition\"}', 8.00, 'Dung phan lon lien tu. Can xem lai vi tri dau phay voi however.', 'graded', '2026-08-14 20:20:00', '2026-08-15 08:45:00'),
(3, 3, 1, 'I used headings first, then I underlined paraphrases in each paragraph before matching the detail questions. The hardest part was ignoring familiar words that did not answer the question directly.', NULL, 8.75, 'Phan hoi tot, cho thay ban da y thuc ve paraphrase va keyword trap.', 'graded', '2026-08-15 19:55:00', '2026-08-16 08:40:00'),
(4, 5, 9, 'Dear Ms. Linh, thank you for your message. The shipment will arrive on Thursday afternoon instead of Wednesday morning. We apologise for the delay and will share the tracking update at 2:00 p.m.', NULL, 84.00, 'Email lich su va day du thong tin. Can bo sung subject line chuyen nghiep hon.', 'graded', '2026-08-14 18:10:00', '2026-08-15 09:15:00'),
(5, 6, 9, NULL, '{\"q1\":\"invoice\",\"q2\":\"approve\",\"q3\":\"budget\",\"q4\":\"applicant\",\"q5\":\"reimburse\"}', NULL, NULL, 'submitted', '2026-08-16 20:00:00', NULL),
(6, 11, 1, 'The foundation course helped me build study habits and basic confidence in answering short listening and reading tasks. I still need to improve writing grammar and linking ideas more naturally.', NULL, 9.00, 'Tong ket chan that, cho thay hoc vien co nhan thuc ro rang ve diem manh va diem can cai thien.', 'graded', '2026-07-04 17:30:00', '2026-07-05 09:20:00'),
(7, 12, 10, NULL, '{\"q1\":\"meeting\",\"q2\":\"confirm\",\"q3\":\"receipt\",\"q4\":\"department\",\"q5\":\"traveler\"}', 78.00, 'Tu vung co tien bo. Can hoc them collocation lien quan den payment va booking.', 'graded', '2026-06-24 18:20:00', '2026-06-25 09:10:00');
