INSERT INTO `question_groups` (`group_id`, `quiz_id`, `assign_id`, `title`, `passage_text`, `image_url`, `audio_url`, `instructions`, `order_num`, `mock_test_id`) VALUES
(1, 1, NULL, 'Listening Set A - Orientation Desk', NULL, NULL, NULL, 'Questions 1-10: nghe doan hoi thoai ve orientation desk va room change.', 1, NULL),
(2, 1, NULL, 'Listening Set B - Library and Student Support', NULL, NULL, NULL, 'Questions 11-20: nghe thong bao ve library workshop va student services.', 2, NULL),
(3, 2, NULL, 'Reading Passage 1 - School Garden Project', 'A secondary school converted its unused rooftop into a supervised garden where students recorded plant growth, rainfall, and insect activity as part of a science unit.', NULL, NULL, 'Questions 1-6 refer to Passage 1.', 1, NULL),
(4, 2, NULL, 'Reading Passage 2 - Community Bike Lanes', 'A city expanded protected bike lanes and later evaluated how often commuters switched from short motorbike trips to bicycles during weekday travel.', NULL, NULL, 'Questions 7-12 refer to Passage 2.', 2, NULL),
(5, 2, NULL, 'Reading Passage 3 - Wetland Restoration', 'Local volunteers restored a wetland near a crowded suburb and monitored bird populations, plant survival, and flood patterns over two rainy seasons.', NULL, NULL, 'Questions 13-18 refer to Passage 3.', 3, NULL),
(6, 3, NULL, 'Writing Task 2', 'Some people believe governments should invest more in public transport than in building new roads for private vehicles.', NULL, NULL, 'Write at least 250 words and support your answer with relevant reasons and examples.', 1, NULL),
(7, 4, NULL, 'Part 5 - Office Grammar and Vocabulary', NULL, NULL, NULL, 'Choose the best answer for each incomplete business sentence.', 1, NULL),
(8, 5, NULL, 'Reading Set 1 - Internal Email', 'An internal email confirms a supplier meeting, revised agenda, and a request to bring updated sales figures.', NULL, NULL, 'Questions 1-6 refer to the internal email.', 1, NULL),
(9, 5, NULL, 'Reading Set 2 - Policy Notice', 'A policy notice explains a new visitor sign-in process and revised equipment booking rules for branch staff.', NULL, NULL, 'Questions 7-12 refer to the policy notice.', 2, NULL),
(10, 5, NULL, 'Reading Set 3 - Service Report', 'A short service report summarises customer waiting time, refund requests, and training actions after a quality review.', NULL, NULL, 'Questions 13-18 refer to the service report.', 3, NULL),
(11, 6, NULL, 'Part 2 - Quick Response', NULL, NULL, NULL, 'Choose the best response for each customer-service question or statement.', 1, NULL),
